local GrainSieveMaker = {}
local PRODUCTS = {
    iron_grainsieve = { name = "Železni sitana za žito", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sitana za žito za mlinarje." },
    bronze_grainsieve = { name = "Bronast sitana za žito", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sitana za žito za mlinarje." },
    silver_grainsieve = { name = "Srebrn sitana za žito", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sitana za žito za mlinarje." },
    gilded_grainsieve = { name = "Pozlačen sitana za žito", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sitana za žito za mlinarje." },
    jewel_set_grainsieve = { name = "Draguljast sitana za žito", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sitana za žito za mlinarje." },
    royal_sovereign_grainsieve = { name = "Kraljevski suveren sitana za žito", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sitana za žito z biseri za krono." },
}
local BUILDINGS = {
    grainsieve_workshop = { name = "Grainsieve delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    grainsieve_house = { name = "Grainsieve hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_grainsieve_atelier = { name = "Mojstrski grainsieve atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_grainsieve_palace = { name = "Suverena grainsieve palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GrainSieveMaker.ironStock=12; GrainSieveMaker.bronzeStock=10; GrainSieveMaker.woodStock=16; GrainSieveMaker.leatherStock=10; GrainSieveMaker.silverStock=8; GrainSieveMaker.goldStock=6; GrainSieveMaker.jewelStock=4; GrainSieveMaker.pearlStock=4
GrainSieveMaker.productStock = {}; GrainSieveMaker.buildings = {}; GrainSieveMaker.maker = nil; GrainSieveMaker.activeMaking = {}; GrainSieveMaker.totalProducts = 0; GrainSieveMaker.dayTimer = 0
function GrainSieveMaker.init() GrainSieveMaker.ironStock=12; GrainSieveMaker.bronzeStock=10; GrainSieveMaker.woodStock=16; GrainSieveMaker.leatherStock=10; GrainSieveMaker.silverStock=8; GrainSieveMaker.goldStock=6; GrainSieveMaker.jewelStock=4; GrainSieveMaker.pearlStock=4; GrainSieveMaker.productStock={}; GrainSieveMaker.buildings={}; GrainSieveMaker.maker=nil; GrainSieveMaker.activeMaking={}; GrainSieveMaker.totalProducts=0; GrainSieveMaker.dayTimer=0; print("[GrainSieveMaker] Royal Grain Sieve Maker System initialized (6 products, 4 buildings)") end
function GrainSieveMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrainSieveMaker.maker={name=n or ("Sitnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sitnikar najet: %s (spretnost: %d)",GrainSieveMaker.maker.name,s),"success") end; return true end
function GrainSieveMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrainSieveMaker.build(id) local ok,e=GrainSieveMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrainSieveMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrainSieveMaker.getQualityBonus() local b=0; for _,bd in ipairs(GrainSieveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrainSieveMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GrainSieveMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GrainSieveMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GrainSieveMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GrainSieveMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GrainSieveMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrainSieveMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrainSieveMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GrainSieveMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GrainSieveMaker.buildings==0 then return false,"Potrebna sitnična delavnica" end; if not GrainSieveMaker.maker then return false,"Potreben sitnikar" end; return true end
function GrainSieveMaker.make(pt,qty) qty=qty or 1; local ok,e=GrainSieveMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GrainSieveMaker.ironStock=GrainSieveMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GrainSieveMaker.bronzeStock=GrainSieveMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GrainSieveMaker.woodStock=GrainSieveMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GrainSieveMaker.leatherStock=GrainSieveMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GrainSieveMaker.silverStock=GrainSieveMaker.silverStock-d.silverCost*qty end; if d.goldCost then GrainSieveMaker.goldStock=GrainSieveMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GrainSieveMaker.jewelStock=GrainSieveMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GrainSieveMaker.pearlStock=GrainSieveMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GrainSieveMaker.maker then t=math.max(1,t-math.floor(GrainSieveMaker.maker.skill/13)) end; table.insert(GrainSieveMaker.activeMaking,{id="grainsieve_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrainSieveMaker.completeMaking(m) local q=1.0+(GrainSieveMaker.getQualityBonus()/100); if GrainSieveMaker.maker then q=q+(GrainSieveMaker.maker.skill/140) end; q=math.min(2.5,q); GrainSieveMaker.productStock[m.productType]=(GrainSieveMaker.productStock[m.productType] or 0)+m.quantity; GrainSieveMaker.totalProducts=GrainSieveMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrainSieveMaker.maker then GrainSieveMaker.maker.itemsMade=GrainSieveMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GrainSieveMaker.maker.skill=math.min(100,GrainSieveMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sito izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"grainsieve.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GrainSieveMaker.update(dt) if not _G.state then return end; GrainSieveMaker.dayTimer=GrainSieveMaker.dayTimer+dt; if GrainSieveMaker.dayTimer>=30 then GrainSieveMaker.dayTimer=0; for i=#GrainSieveMaker.activeMaking,1,-1 do local m=GrainSieveMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrainSieveMaker.completeMaking(m); table.remove(GrainSieveMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrainSieveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrainSieveMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrainSieveMaker.getStats() return {ironStock=GrainSieveMaker.ironStock,bronzeStock=GrainSieveMaker.bronzeStock,woodStock=GrainSieveMaker.woodStock,leatherStock=GrainSieveMaker.leatherStock,silverStock=GrainSieveMaker.silverStock,goldStock=GrainSieveMaker.goldStock,jewelStock=GrainSieveMaker.jewelStock,pearlStock=GrainSieveMaker.pearlStock,productStock=GrainSieveMaker.productStock,numBuildings=#GrainSieveMaker.buildings,hasMaker=GrainSieveMaker.maker~=nil,makerName=GrainSieveMaker.maker and GrainSieveMaker.maker.name or "—",makerSkill=GrainSieveMaker.maker and GrainSieveMaker.maker.skill or 0,activeMaking=#GrainSieveMaker.activeMaking,totalProducts=GrainSieveMaker.totalProducts} end
return GrainSieveMaker
